<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
type Problem = { name: string; content: string; expected: string; source?: string }
type Prover = { id: string; name: string; version: string; installed: boolean; executable: string }
type Result = { prover: string; problem: string; expected: string; state: string; status: string; wall_seconds: number; cpu_seconds: number | null; peak_rss_kb: number | null; output_present: boolean; error: string | null }
type Standing = { prover: string; completed: number; matches: number; claims: number; wrong: number; timeouts: number; errors: number; output_count: number; unique_matches: number; average_cpu: number | null; average_wall: number | null; maximum_rss_mb: number | null; sotac: number }
type Batch = { id: string; name: string; created: number; state: string; seconds: number; total: number; results: Result[]; problems: Problem[]; provers: string[]; manifest: unknown; error: string | null }
type Summary = { id: string; name: string; created: number; state: string; total: number; completed: number }
type Detail = { batch: Batch; standings: Standing[] }
type LibraryInfo = { available: boolean; root?: string; version?: string; total?: number; domains?: Record<string, number>; formats?: Record<string, number>; error?: string }
type LibraryEntry = { id: string; name: string; domain: string; format: string; expected: string; title?: string; rating?: string; error?: string }
type LibraryPage = { total: number; offset: number; limit: number; entries: LibraryEntry[] }
const library = ref<LibraryInfo | null>(null), libraryPage = ref<LibraryPage | null>(null)
const libraryQuery = ref(''), libraryDomain = ref(''), libraryFormat = ref(''), librarySelected = ref<string[]>([]), libraryBusy = ref(false), libraryMessage = ref('')
let libraryRequest = 0
async function searchLibrary(offset=0){const request=++libraryRequest;libraryBusy.value=true;error.value='';try{const params=new URLSearchParams({q:libraryQuery.value,domain:libraryDomain.value,format:libraryFormat.value,offset:String(offset)});const result=await api<LibraryPage>('/api/library/problems?'+params);if(request===libraryRequest)libraryPage.value=result}catch(e){if(request===libraryRequest)error.value=String(e)}finally{if(request===libraryRequest)libraryBusy.value=false}}
async function importLibrary(){libraryBusy.value=true;error.value='';libraryMessage.value='';try{const result=await api<{problems:Problem[]}>('/api/library/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:librarySelected.value})});const existing=new Set(problems.value.map(p=>p.name));const additions=result.problems.filter(p=>!existing.has(p.name));if(problems.value.length+additions.length>100)throw Error('A suite can contain up to 100 problems. Remove some before importing.');const first=problems.value.length;problems.value.push(...additions);if(additions.length)selectedProblem.value=first;libraryMessage.value=`Added ${additions.length} problem(s), with required axioms expanded. ${result.problems.length-additions.length} duplicate(s) skipped.`;librarySelected.value=[]}catch(e){error.value=String(e)}finally{libraryBusy.value=false}}
function preference(key:string,fallback:string){try{return localStorage.getItem(key)??fallback}catch{return fallback}}
const theme=ref(preference('atp-theme',window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'))
const layout=ref(preference('atp-layout','comfortable'))
watch([theme,layout],()=>{document.documentElement.dataset.theme=theme.value;document.documentElement.dataset.layout=layout.value;try{localStorage.setItem('atp-theme',theme.value);localStorage.setItem('atp-layout',layout.value)}catch{}},{immediate:true})
const page = ref('benchmarks'), suiteName = ref('First-order smoke suite'), seconds = ref(5)
const problems = ref<Problem[]>([]), selectedProblem = ref(0), provers = ref<Prover[]>([]), selected = ref<string[]>([])
const history = ref<Summary[]>([]), detail = ref<Detail | null>(null), busy = ref(false), error = ref(''), connected = ref(false), logs = ref<string | null>(null), logTitle = ref('')
let timer: ReturnType<typeof setInterval> | undefined
const statuses = ['Theorem', 'Unsatisfiable', 'Satisfiable', 'CounterSatisfiable', 'Unknown']
const colors = ['var(--accent)', 'var(--op)', 'var(--ok)']
const active = computed(() => detail.value?.batch.state === 'running')
const current = computed(() => problems.value[selectedProblem.value])
const progress = computed(() => detail.value ? Math.round(detail.value.batch.results.length / detail.value.batch.total * 100) : 0)
const matches = computed(() => detail.value?.standings.reduce((n,s)=>n+s.matches,0) ?? 0)
const cpuTotal = computed(()=>detail.value?.batch.results.reduce((n,r)=>n+(r.cpu_seconds??0),0)??0)
const wrong = computed(()=>detail.value?.standings.reduce((n,s)=>n+s.wrong,0)??0)
const nameOf = (id:string)=>provers.value.find(p=>p.id===id)?.name??id
const fmt = (n:number|null|undefined,d=3)=>n==null?'—':n.toFixed(d)
const time = (n:number)=>new Date(n*1000).toLocaleString()
function samples(){problems.value=[{name:'implication.p',expected:'Theorem',content:'% Status : Theorem\nfof(a1, axiom, a).\nfof(a2, axiom, b).\nfof(a3, axiom, (a & b) => z).\nfof(goal, conjecture, z).\n'},{name:'contradiction.p',expected:'Unsatisfiable',content:'% Status : Unsatisfiable\ncnf(positive, axiom, p).\ncnf(negative, axiom, ~p).\n'}];selectedProblem.value=0}
async function api<T>(url:string,options?:RequestInit):Promise<T>{const r=await fetch(url,options);if(!r.ok){let message=r.statusText;try{message=(await r.json()).error??message}catch{}throw Error(message)}return r.json()}
async function refreshHistory(){history.value=await api<Summary[]>('/api/batches')}
async function load(id:string){const changed=detail.value?.batch.id!==id;detail.value=await api<Detail>('/api/batches/'+id);if(changed){suiteName.value=detail.value.batch.name;seconds.value=detail.value.batch.seconds;selected.value=[...detail.value.batch.provers];problems.value=detail.value.batch.problems.map(p=>({...p}));selectedProblem.value=0}}
async function run(){error.value='';busy.value=true;try{const result=await api<{id:string}>('/api/batches',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:suiteName.value,seconds:seconds.value,problems:problems.value,provers:selected.value})});await load(result.id);await refreshHistory();page.value='benchmarks'}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
async function cancel(){if(!detail.value)return;try{await api('/api/batches/'+detail.value.batch.id+'/cancel',{method:'POST'})}catch(e){error.value=String(e)}}
async function upload(event:Event){const input=event.target as HTMLInputElement;error.value='';try{for(const file of Array.from(input.files??[])){if(file.size>1024*1024)throw Error(file.name+' is larger than 1 MB');const content=await file.text();const raw=content.match(/%\s*Status\s*:\s*(Theorem|Unsatisfiable|CounterSatisfiable|Satisfiable)/i)?.[1]??'Unknown';const expected=statuses.find(s=>s.toLowerCase()===raw.toLowerCase())??'Unknown';let name=file.name;let suffix=2;while(problems.value.some(p=>p.name===name))name=file.name+'-'+suffix++;problems.value.push({name,content,expected})}selectedProblem.value=Math.max(0,problems.value.length-1)}catch(e){error.value=String(e)}input.value=''}
function add(){let n=problems.value.length+1;while(problems.value.some(p=>p.name===`problem-${n}.p`))n++;problems.value.push({name:`problem-${n}.p`,content:'',expected:'Unknown'});selectedProblem.value=problems.value.length-1}
function remove(){problems.value.splice(selectedProblem.value,1);selectedProblem.value=Math.max(0,selectedProblem.value-1)}
async function openOutput(index:number){if(!detail.value)return;try{const r=await fetch(`/api/batches/${detail.value.batch.id}/output/${index}`);if(!r.ok)throw Error('Output unavailable');logs.value=await r.text();const row=detail.value.batch.results[index];logTitle.value=row?nameOf(row.prover)+' / '+row.problem:'Output'}catch(e){error.value=String(e)}}
function download(name:string,content:string,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportJson(){if(detail.value)download('atp-benchmark-'+detail.value.batch.id+'.json',JSON.stringify(detail.value,null,2))}
function matching(row:Result){return statuses.slice(0,4).includes(row.expected)&&row.expected===row.status}
function chart(){const d=detail.value;if(!d)return[];return d.batch.provers.map((id,index)=>{const solved=d.batch.results.filter(r=>r.prover===id&&matching(r)&&r.cpu_seconds!=null).map(r=>r.cpu_seconds!).sort((a,b)=>a-b);let total=0;return{id,color:colors[index%colors.length],points:[{x:0,y:0},...solved.map((v,i)=>({x:total+=v,y:i+1}))]}})}
const series=computed(chart)
const maxX=computed(()=>Math.max(.01,...series.value.flatMap(s=>s.points.map(p=>p.x))))
const maxY=computed(()=>Math.max(1,detail.value?.batch.problems.length??problems.value.length))
const polyline=(points:{x:number;y:number}[])=>points.map(p=>`${50+p.x/maxX.value*500},${160-p.y/maxY.value*130}`).join(' ')
onMounted(async()=>{samples();try{await api('/api/health');connected.value=true;provers.value=await api<Prover[]>('/api/provers');selected.value=provers.value.filter(p=>p.installed).map(p=>p.id);await refreshHistory();const latest=history.value[0];if(latest)await load(latest.id);library.value=await api<LibraryInfo>('/api/library');if(library.value.available)await searchLibrary()}catch(e){error.value='Cannot reach the Rust API. Start cargo run -p atp-server. '+String(e)}timer=setInterval(async()=>{if(detail.value?.batch.state==='running'){try{await load(detail.value.batch.id);if(!active.value)await refreshHistory()}catch(e){error.value=String(e)}}},700)})
onUnmounted(()=>clearInterval(timer))
</script>

<template>
<div class="shell">
  <div class="workspace">
    <header class="app-header">
      <a href="#" class="brand" @click.prevent="page='benchmarks'" aria-label="ATPWorkbench home">
        <svg class="brand-icon" viewBox="0 0 50 50" fill="none" aria-hidden="true"><rect x="1" y="1" width="48" height="48" rx="10"/><path d="M13 35 25 13 37 35M18 27h14"/><circle cx="25" cy="13" r="3"/><circle cx="13" cy="35" r="3"/><circle cx="37" cy="35" r="3"/></svg>
        <div class="brand-text"><h1>ATPWorkbench</h1><p class="sub">Run and compare local automated theorem provers</p></div>
      </a>
      <div class="head-meta"><span class="connection"><span :class="['dot',{online:connected}]"></span>{{connected?'Local runner connected':'Runner disconnected'}}</span><div class="head-controls">
        <button class="head-btn" @click="layout=layout==='comfortable'?'wide':'comfortable'" :title="layout==='comfortable'?'Switch to wide layout':'Switch to comfortable layout'">{{layout==='comfortable'?'Wide layout':'Comfortable layout'}}</button>
        <button class="head-btn theme-btn" @click="theme=theme==='light'?'dark':'light'" :title="theme==='light'?'Switch to dark theme':'Switch to light theme'" :aria-label="theme==='light'?'Switch to dark theme':'Switch to light theme'">
          <svg v-if="theme==='light'" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z"/></svg>
          <svg v-else width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg>
        </button>
      </div></div>
    </header>
    <nav class="tabs" aria-label="Workspace"><div class="tab-group" data-label="Run"><button :class="{selected:page==='benchmarks'}" :aria-current="page==='benchmarks'?'page':undefined" @click="page='benchmarks'">ProverBench</button><button :class="{selected:page==='suite'}" :aria-current="page==='suite'?'page':undefined" @click="page='suite'">Test suite</button></div><div class="tab-group" data-label="Manage"><button :class="{selected:page==='history'}" :aria-current="page==='history'?'page':undefined" @click="page='history'">Run history</button><button :class="{selected:page==='provers'}" :aria-current="page==='provers'?'page':undefined" @click="page='provers'">Prover registry <span class="tab-badge">{{provers.length}}</span></button></div></nav>
    <label class="tab-select"><span>Section</span><select v-model="page" aria-label="Section"><optgroup label="Run"><option value="benchmarks">ProverBench</option><option value="suite">Test suite</option></optgroup><optgroup label="Manage"><option value="history">Run history</option><option value="provers">Prover registry</option></optgroup></select></label>
    <main><div class="page-heading"><h2>{{page==='benchmarks'?'ProverBench':page==='suite'?'Test suite':page==='history'?'Run history':'Prover registry'}}</h2><p>{{page==='benchmarks'?'Run the same problems across local ATPs and compare answers, time and resource use.':page==='suite'?'Import local TPTP problems or upload your own, then define a test suite.':page==='history'?'Reopen saved experiments, inspect output and export results.':'Installed adapters are separate from the exact 92-entry catalogue target.'}}</p></div>
  <div v-if="error" class="error" role="alert">{{error}}<button @click="error=''" aria-label="Dismiss error">×</button></div>

  <template v-if="page==='benchmarks'||page==='suite'">
  <section class="card setup"><div class="section-heading"><div><span class="section-number">01</span><h2>Configure experiment</h2></div><span class="muted">Sequential execution · one core per adapter request</span></div><div class="setup-grid"><label>Suite name<input v-model="suiteName" :disabled="active" maxlength="120"></label><label>CPU budget per problem<div class="unit-input"><input v-model.number="seconds" type="number" min="1" max="300" :disabled="active"><span>seconds</span></div></label><div><label class="field-label">Provers</label><div class="prover-options"><label v-for="p in provers" :key="p.id" :class="['prover-choice',{checked:selected.includes(p.id)}]"><input v-model="selected" type="checkbox" :value="p.id" :disabled="!p.installed||active"><span>{{p.name}}<small>{{p.version}}</small></span></label></div></div></div><div class="setup-bottom"><div><strong>{{problems.length}}</strong> problems <span>×</span> <strong>{{selected.length}}</strong> provers <span>=</span> <strong>{{problems.length*selected.length}}</strong> executions <small>Wall cutoff: CPU budget + 5s per execution</small></div><div class="actions"><button @click="page=page==='suite'?'benchmarks':'suite'">{{page==='suite'?'View results':'Edit suite'}}</button><button v-if="active" class="danger" @click="cancel">Cancel suite</button><button class="primary" :disabled="active||busy||!connected||!problems.length||!selected.length" @click="run"><span>▶</span> {{busy?'Starting…':'Run test suite'}}</button></div></div></section>

  <section v-if="page==='suite'" class="card library-browser"><div class="section-heading"><div><span class="section-number">02</span><h2>TPTP library</h2></div><span class="muted">{{library?.available?`${library.total?.toLocaleString()} local problems`:'Not configured'}}</span></div>
    <template v-if="library?.available"><div class="library-intro"><p><strong>{{library.version}}</strong><br>Browse the full problem library. CASC competition sets are selected subsets.</p><p class="path">{{library.root}}</p></div>
    <form class="library-filters" @submit.prevent="searchLibrary()"><label>Problem filename<input v-model="libraryQuery" placeholder="e.g. PUZ001" maxlength="80"></label><label>Domain<select v-model="libraryDomain"><option value="">All domains</option><option v-for="(count,domain) in library.domains" :key="domain" :value="domain">{{domain}} ({{count}})</option></select></label><label>Language<select v-model="libraryFormat"><option value="">All languages</option><option v-for="(count,format) in library.formats" :key="format" :value="format">{{format}} ({{count}})</option></select></label><button type="submit" :disabled="libraryBusy">{{libraryBusy?'Loading…':'Search'}}</button></form>
    <div class="table-wrap"><table><thead><tr><th>Select</th><th>Problem</th><th>Language</th><th>Expected</th><th>Rating</th></tr></thead><tbody><tr v-for="entry in libraryPage?.entries??[]" :key="entry.id"><td><input type="checkbox" v-model="librarySelected" :value="entry.id" :aria-label="`Select ${entry.name}`" :disabled="active||libraryBusy||!!entry.error"></td><td><strong>{{entry.name}}</strong><small class="library-title">{{entry.title??entry.error}}</small></td><td>{{entry.format}}</td><td>{{entry.expected}}</td><td class="muted" :title="entry.rating">{{entry.rating?.split(',')[0]??'—'}}</td></tr><tr v-if="libraryPage&&!libraryPage.total"><td colspan="5" class="empty">No matching problems.</td></tr></tbody></table></div>
    <div class="library-bottom"><div class="actions"><button :disabled="libraryBusy||!libraryPage?.offset" @click="searchLibrary(Math.max(0,(libraryPage?.offset??0)-20))">Previous</button><span class="muted">{{libraryPage?.total?`${(libraryPage.offset??0)+1}–${Math.min((libraryPage.offset??0)+20,libraryPage.total)} of ${libraryPage.total.toLocaleString()}`:'0 results'}}</span><button :disabled="libraryBusy||!libraryPage||libraryPage.offset+20>=libraryPage.total" @click="searchLibrary((libraryPage?.offset??0)+20)">Next</button></div><button class="primary" :disabled="active||libraryBusy||!librarySelected.length" @click="importLibrary">Add selected ({{librarySelected.length}})</button></div><p v-if="libraryMessage" class="library-message" role="status">{{libraryMessage}}</p><p class="footnote">Imports resolve include directives and selected axioms into self-contained input. Limit: 100 problems per suite, 1 MB per problem including source dependencies. Importing does not start a run.</p></template>
    <p v-else class="footnote">{{library?.error??'Configure ATP_TPTP_ROOT or data/library.json, then restart the Rust server to browse your local TPTP library.'}}</p>
  </section>

  <section v-if="page==='suite'" class="card suite-editor"><div class="section-heading"><div><span class="section-number">03</span><h2>Problems</h2></div><div class="actions"><button @click="samples" :disabled="active">Load examples</button><button @click="problems=[];selectedProblem=0" :disabled="active||!problems.length">Clear suite</button><button @click="add" :disabled="active">+ Add problem</button><label class="button">Upload files<input type="file" multiple accept=".p,.tptp,.fof,.cnf,.txt" hidden @change="upload" :disabled="active"></label></div></div><div class="editor-layout"><div class="problem-list"><button v-for="(p,i) in problems" :key="i" :class="{chosen:i===selectedProblem}" @click="selectedProblem=i"><span>{{String(i+1).padStart(2,'0')}}</span><div>{{p.name}}<small>{{p.expected}}</small></div></button></div><div v-if="current" class="problem-editor"><div class="editor-fields"><label>Problem name<input v-model="current.name" :disabled="active"></label><label>Expected SZS status<select v-model="current.expected" :disabled="active"><option v-for="s in statuses" :key="s">{{s}}</option></select></label><button @click="remove" :disabled="active" class="text-danger">Remove</button></div><p v-if="current.source" class="problem-source">Source: {{current.source}}</p><textarea v-model="current.content" @input="current.source=undefined" :disabled="active" spellcheck="false" aria-label="TPTP problem"></textarea><p class="muted">Unknown expectations are retained but excluded from expected-status match rankings. Use the library importer for files with include directives.</p></div></div></section>

  <template v-if="page==='benchmarks'"><div class="metrics"><article><span>PROBLEMS IN SUITE</span><strong>{{detail?.batch.problems.length??problems.length}}</strong><small>{{detail?.batch.name??suiteName}}</small></article><article><span>EXPECTED-STATUS MATCHES</span><strong>{{matches}}<em>/ {{detail?.batch.total??'—'}}</em></strong><small>Prover claims · not proof-validated</small></article><article><span>RECORDED CPU TIME</span><strong>{{fmt(cpuTotal,2)}}<em>s</em></strong><small>User + system · unavailable measurements omitted</small></article><article><span>EXPERIMENT STATUS</span><strong class="state-value">{{detail?.batch.state??'Ready'}}</strong><small>{{detail?`${detail.batch.results.length} of ${detail.batch.total} executions complete`:'Configure a suite to get started'}}</small></article></div>
  <section class="card results"><div class="section-heading"><div><span class="section-number">02</span><h2>Leaderboard</h2><span v-if="active" class="running">Running</span></div><div class="actions"><button :disabled="!detail" @click="exportJson">Export JSON</button><a v-if="detail" :href="`/api/batches/${detail.batch.id}/export.csv`" class="button">↓ Export CSV</a></div></div><div v-if="detail" class="progress"><span :style="{width:progress+'%'}"></span></div><div class="table-wrap"><table><thead><tr><th>Rank / prover</th><th>Matches</th><th>Avg CPU s</th><th>Avg wall s</th><th>Peak MiB</th><th>Unique</th><th>SotAC*</th><th>Timeouts</th><th>Errors / wrong</th></tr></thead><tbody><tr v-for="(s,i) in detail?.standings??[]" :key="s.prover"><td><span class="rank">{{String(i+1).padStart(2,'0')}}</span><strong>{{nameOf(s.prover)}}</strong></td><td><span class="match-count">{{s.matches}}</span><span class="muted"> / {{detail?.batch.problems.length}}</span></td><td>{{fmt(s.average_cpu)}}</td><td>{{fmt(s.average_wall)}}</td><td>{{fmt(s.maximum_rss_mb,1)}}</td><td>{{s.unique_matches}}</td><td>{{fmt(s.sotac,2)}}</td><td>{{s.timeouts}}</td><td :class="{'text-danger':s.errors||s.wrong}">{{s.errors}} / {{s.wrong}}</td></tr><tr v-if="!detail"><td colspan="9" class="empty">Your first experiment starts here.<small>Run the included smoke suite to compare your installed provers.</small></td></tr></tbody></table></div><p class="footnote">CASC-inspired ranking: expected-status matches, then average CPU time on matching answers. Proof/model output is recorded, but acceptance is not validated. *SotAC averages the fraction of selected systems that did not match, excluding universally matched problems.</p><p v-if="wrong" class="wrong-alert">{{wrong}} answer(s) conflict with expected statuses. Investigate these runs before drawing conclusions.</p></section>
  <div class="analysis-grid"><section class="card"><div class="section-heading"><div><span class="section-number">03</span><h2>Performance profile</h2></div><span class="muted">Cumulative CPU time</span></div><div class="legend"><span v-for="s in series" :key="s.id"><i :style="{background:s.color}"></i>{{nameOf(s.id)}}</span></div><svg viewBox="0 0 600 200" role="img" aria-label="Cumulative matching problems by CPU time"><g v-for="i in 5" :key="i"><line x1="50" x2="550" :y1="160-(i-1)*32.5" :y2="160-(i-1)*32.5" stroke="var(--line)"/><text x="37" :y="164-(i-1)*32.5" text-anchor="end">{{fmt((i-1)*maxY/4,1)}}</text></g><line x1="50" x2="550" y1="160" y2="160" stroke="var(--line)"/><polyline v-for="s in series" :key="s.id" :points="polyline(s.points)" fill="none" :stroke="s.color" stroke-width="2.5"/><text x="50" y="184">0s</text><text x="550" y="184" text-anchor="end">{{fmt(maxX)}}s</text><text x="300" y="198" text-anchor="middle">Cumulative CPU seconds · expected-status matches</text></svg></section><section class="card methodology"><h2>Benchmark notes</h2><p>Every selected prover receives every problem, under the same requested time budget. Matches depend on your expected status.</p><div><span>Execution</span><strong>Local · sequential</strong></div><div><span>Proof validation</span><strong>Not yet implemented</strong></div><div><span>Exact catalogue target</span><strong>0 / 92 verified setups</strong></div><a href="https://tptp.org/CASC/J13/Design.html" target="_blank" rel="noreferrer">Read the CASC evaluation rules ↗</a></section></div>
  <section v-if="detail" class="card"><div class="section-heading"><div><span class="section-number">04</span><h2>Individual executions</h2></div><span class="muted">{{detail.batch.name}} · {{time(detail.batch.created)}}</span></div><div class="table-wrap"><table><thead><tr><th>Problem</th><th>Prover</th><th>Expected</th><th>Reported</th><th>CPU / wall s</th><th>Proof/model block</th><th>Output</th></tr></thead><tbody><tr v-for="(r,i) in detail.batch.results" :key="i"><td>{{r.problem}}</td><td>{{nameOf(r.prover)}}</td><td>{{r.expected}}</td><td><span :class="['status',matching(r)?'success':r.status==='Timeout'?'timeout':r.error?'failure':'neutral']">{{r.status}}</span></td><td>{{fmt(r.cpu_seconds)}} / {{fmt(r.wall_seconds)}}</td><td>{{r.output_present?'Present · unchecked':'Not found'}}</td><td><button class="small" @click="openOutput(i)">View log ↗</button></td></tr></tbody></table></div></section>
  </template></template>

  <section v-if="page==='history'" class="card"><div class="section-heading"><h2>Saved experiments</h2><button @click="refreshHistory">Refresh</button></div><table><thead><tr><th>Experiment</th><th>Started</th><th>Status</th><th>Executions</th><th></th></tr></thead><tbody><tr v-for="b in history" :key="b.id"><td><strong>{{b.name}}</strong></td><td>{{time(b.created)}}</td><td>{{b.state}}</td><td>{{b.completed}} / {{b.total}}</td><td><button @click="load(b.id).then(()=>page='benchmarks').catch(e=>error=String(e))">Open results</button></td></tr><tr v-if="!history.length"><td colspan="5" class="empty">No experiments saved yet.</td></tr></tbody></table></section>
  <section v-if="page==='provers'" class="card"><div class="section-heading"><h2>Installed adapters</h2><span class="muted">Exact online versions are not certified</span></div><table><thead><tr><th>Prover</th><th>Version</th><th>Availability</th><th>Executable</th></tr></thead><tbody><tr v-for="p in provers" :key="p.id"><td><strong>{{p.name}}</strong></td><td>{{p.version}}</td><td><span :class="['status',p.installed?'success':'failure']">{{p.installed?'Installed':'Missing'}}</span></td><td class="path">{{p.executable}}</td></tr></tbody></table><p class="footnote">These are explicitly configured local adapters. The reference catalogue describes 92 target setups; it does not install them.</p></section>
  <footer>ATPWorkbench / ProverBench<span>Local execution. Reproducible experiments.</span></footer>
  </main></div>
  <div v-if="logs!==null" class="modal-backdrop" @click.self="logs=null"><section class="log-modal" role="dialog" aria-modal="true" aria-label="Prover output"><div class="section-heading"><h2>{{logTitle}}</h2><div class="actions"><button @click="download('prover-output.txt',logs??'','text/plain')">Download log</button><button @click="logs=null" aria-label="Close output">Close ×</button></div></div><pre>{{logs}}</pre></section></div>
</div>
</template>
